// Caching Strategy: Spatial Locality via Loop Ordering

int matrix[1000][1000];
const int N = 1000;

// Optimized Access (Good Locality: Row-Major order in C/C++)
// Cache lines are filled sequentially. High spatial hit rate.
for (int r = 0; r < N; ++r)
  for (int c = 0; c < N; ++c)
    matrix[r][c] = r + c;

// Suboptimal Access (Poor Locality: Column-Major access)
// Forces large memory jumps (stride N * sizeof(int)). Cache thrashing.
for (int c = 0; c < N; ++c)
  for (int r = 0; r < N; ++r)
    matrix[r][c] = r + c;

// Temporal Locality Hint: Reuse data recently fetched (e.g., inner loop data)
int temp_sum = 0;
for (int i = 0; i < N; ++i) {
    // Repeated access to matrix[i][j] is temporally local
    for (int j = 0; j < 10; ++j)
        temp_sum += matrix[i][0];
}
